using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

public class PurifyOmensHandler : ReferenceSingleton<PurifyOmensHandler>
{
	[NonSerialized]
	public List<Action> OnPlayerDealPurifyOmenActions = new List<Action>();

	[NonSerialized]
	public List<Action> OnPlayerDealPurifyOnEnemyOmenActions = new List<Action>();

	[NonSerialized]
	public List<Action> OnPlayerDealPurifyOnSentinelsOmenActions = new List<Action>();

	[NonSerialized]
	public List<Func<int, int>> OnPlayerDealPurifyStartModifierOmenActions = new List<Func<int, int>>();

	[NonSerialized]
	public List<Func<int, GameObject, int>> OnPlayerDealPurifyOnTargetModifierOmenActions = new List<Func<int, GameObject, int>>();

	[NonSerialized]
	public Action<float> ZenithRingFeedbackAction;

	[NonSerialized]
	public Action AzimuthRingFeedbackAction;

	[NonSerialized]
	public Func<int, int> OnPlayerDealPurifyBlazarDiskOmenAction;

	[NonSerialized]
	public List<Func<int, int>> OnPlayerDealPurifyFinalModifierOmenActions = new List<Func<int, int>>();

	[NonSerialized]
	public Action<GameObject> OnEnemyPurifiedSyzygyStarDealCorruptionOmenAction;

	[NonSerialized]
	public List<Func<int, int>> OnAnyTargetReceivePurifyModifierOmenActions = new List<Func<int, int>>();

	[NonSerialized]
	public List<Func<int, int>> OnEnemyReceivePurifyModifierOmenActions = new List<Func<int, int>>();

	[NonSerialized]
	public Action DicesmithHelmetAction;

	[NonSerialized]
	public List<Action<int>> OnPlayerAndSentinelsExceededPurifyActions = new List<Action<int>>();

	[NonSerialized]
	public List<Action<GameObject>> OnPlayerDealPurifyWithTargetOmenActions = new List<Action<GameObject>>();

	public void OnPlayerDealPurify()
	{
		for (int i = 0; i < OnPlayerDealPurifyOmenActions.Count; i++)
		{
			OnPlayerDealPurifyOmenActions[i]();
		}
	}

	public void OnPlayerDealPurifyOnEnemies()
	{
		for (int i = 0; i < OnPlayerDealPurifyOnEnemyOmenActions.Count; i++)
		{
			OnPlayerDealPurifyOnEnemyOmenActions[i]();
		}
	}

	public void OnPlayerDealPurifyOnSentinels()
	{
		for (int i = 0; i < OnPlayerDealPurifyOnSentinelsOmenActions.Count; i++)
		{
			OnPlayerDealPurifyOnSentinelsOmenActions[i]();
		}
	}

	public int OnPlayerDealPurifyStartModifiers(int purifyAmount)
	{
		for (int i = 0; i < OnPlayerDealPurifyStartModifierOmenActions.Count; i++)
		{
			purifyAmount = OnPlayerDealPurifyStartModifierOmenActions[i](purifyAmount);
		}
		return purifyAmount;
	}

	public int OnPlayerDealPurifyBlazarDiskModifier(int purifyAmount)
	{
		if (OnPlayerDealPurifyBlazarDiskOmenAction != null)
		{
			purifyAmount = OnPlayerDealPurifyBlazarDiskOmenAction(purifyAmount);
		}
		return purifyAmount;
	}

	public void OnPlayerPurifiedCorruptedCheckZenithRingOmenFeedback(float playerCurrentCorruption)
	{
		ZenithRingFeedbackAction?.Invoke(playerCurrentCorruption);
	}

	public void OnPlayerHeartModifiedCheckAzimuthRingOmenFeedback()
	{
		AzimuthRingFeedbackAction?.Invoke();
	}

	public int OnPlayerDealPurifyOnTargetModifier(int purifyAmount, GameObject target)
	{
		for (int i = 0; i < OnPlayerDealPurifyOnTargetModifierOmenActions.Count; i++)
		{
			purifyAmount = OnPlayerDealPurifyOnTargetModifierOmenActions[i](purifyAmount, target);
		}
		return purifyAmount;
	}

	public int OnPlayerDealPurifyFinalModifier(int purifyAmount)
	{
		for (int i = 0; i < OnPlayerDealPurifyFinalModifierOmenActions.Count; i++)
		{
			purifyAmount = OnPlayerDealPurifyFinalModifierOmenActions[i](purifyAmount);
		}
		return purifyAmount;
	}

	public void OnEnemyPurifiedSyzygyStarDealCorruption(GameObject enemy)
	{
		OnEnemyPurifiedSyzygyStarDealCorruptionOmenAction?.Invoke(enemy);
	}

	public int OnAnyTargetReceivePurifyModifiers(int purifyAmount)
	{
		for (int i = 0; i < OnAnyTargetReceivePurifyModifierOmenActions.Count; i++)
		{
			purifyAmount = OnAnyTargetReceivePurifyModifierOmenActions[i](purifyAmount);
		}
		return purifyAmount;
	}

	public int OnEnemiesReceivePurifyModifiers(int purifyAmount)
	{
		for (int i = 0; i < OnEnemyReceivePurifyModifierOmenActions.Count; i++)
		{
			purifyAmount = OnEnemyReceivePurifyModifierOmenActions[i](purifyAmount);
		}
		return purifyAmount;
	}

	public void DiceAddedToDicePoolCheckDicesmithHelmetAction()
	{
		DicesmithHelmetAction?.Invoke();
	}

	public void OnPlayerAndSentinelsExceededPurify(int exceedPurifyAmount)
	{
		for (int i = 0; i < OnPlayerAndSentinelsExceededPurifyActions.Count; i++)
		{
			OnPlayerAndSentinelsExceededPurifyActions[i](exceedPurifyAmount);
		}
	}

	public void OnPlayerDealOnPlayerDealPurifyWithTarget(GameObject target)
	{
		for (int i = 0; i < OnPlayerDealPurifyWithTargetOmenActions.Count; i++)
		{
			OnPlayerDealPurifyWithTargetOmenActions[i](target);
		}
	}
}
